function validate([grid, k]) {
  if (!Array.isArray(grid) || grid.length < 1 || grid.length > 40) return 'grid needs 1 to 40 rows.';
  const n = grid[0].length;
  if (n < 1 || n > 40) return 'Each row needs 1 to 40 cells.';
  if (grid.some(row => !Array.isArray(row) || row.length !== n)) return 'All rows must have the same length.';
  if (grid.some(row => row.some(v => v !== 0 && v !== 1))) return 'Every cell is 0 or 1.';
  if (grid[0][0] !== 0 || grid[grid.length - 1][n - 1] !== 0) return 'The top-left and bottom-right cells must be 0.';
  if (!Number.isInteger(k) || k < 1 || k > grid.length * n) return 'k is between 1 and m * n.';
  return null;
}

