function shortestPath(grid, k) {
  const rows = grid.length;
  const cols = grid[0].length;
  if (k >= rows + cols - 2) return rows + cols - 2;

  const best = Array.from({ length: rows }, () => new Array(cols).fill(-1));
  const directions = [[1, 0], [-1, 0], [0, 1], [0, -1]];
  best[0][0] = k;
  let queue = [[0, 0, k]];
  let steps = 0;

  while (queue.length > 0) {
    const next = [];
    for (const [row, col, budget] of queue) {
      if (row === rows - 1 && col === cols - 1) return steps;
      for (const [dr, dc] of directions) {
        const r = row + dr;
        const c = col + dc;
        if (r < 0 || r >= rows || c < 0 || c >= cols) continue;
        const remaining = budget - grid[r][c];
        if (remaining < 0 || remaining <= best[r][c]) continue;
        best[r][c] = remaining;
        next.push([r, c, remaining]);
      }
    }
    queue = next;
    steps++;
  }
  return -1;
}

