function shortestPath(grid, k) {
  // Bellman-Ford style relaxation over (cell, obstacles removed) until nothing improves.
  const m = grid.length, n = grid[0].length, used = Math.min(k, m * n);
  const dist = Array.from({ length: used + 1 }, () => Array.from({ length: m }, () => new Array(n).fill(Infinity)));
  dist[0][0][0] = 0;
  let changed = true;
  while (changed) {
    changed = false;
    for (let j = 0; j <= used; j++) {
      for (let i = 0; i < m; i++) {
        for (let c = 0; c < n; c++) {
          const here = dist[j][i][c];
          if (here === Infinity) continue;
          for (const [x, y] of [[i + 1, c], [i - 1, c], [i, c + 1], [i, c - 1]]) {
            if (x < 0 || x >= m || y < 0 || y >= n) continue;
            const jj = j + grid[x][y];
            if (jj > used) continue;
            if (here + 1 < dist[jj][x][y]) { dist[jj][x][y] = here + 1; changed = true; }
          }
        }
      }
    }
  }
  let answer = Infinity;
  for (let j = 0; j <= used; j++) answer = Math.min(answer, dist[j][m - 1][n - 1]);
  return answer === Infinity ? -1 : answer;
}

