function generate(rand, size) {
  const pick = k => Math.floor(rand() * k);
  const m = size === 'large' ? 30 + pick(11) : 1 + pick(5);
  const n = size === 'large' ? 30 + pick(11) : 1 + pick(5);
  const density = size === 'large' ? 0.3 + rand() * 0.3 : [0.2, 0.4, 0.6, 0.8][pick(4)];
  const grid = Array.from({ length: m }, () => Array.from({ length: n }, () => (rand() < density ? 1 : 0)));
  if (size === 'large' && rand() < 0.5) {
    // A winding maze: full walls on every other row with one gap at alternating ends, so detours are long.
    for (let r = 0; r < m; r++) for (let c = 0; c < n; c++) grid[r][c] = r % 2 === 1 ? 1 : (rand() < 0.05 ? 1 : 0);
    for (let r = 1; r < m; r += 2) grid[r][r % 4 === 1 ? n - 1 : 0] = 0;
  }
  grid[0][0] = 0;
  grid[m - 1][n - 1] = 0;
  // Mostly small budgets, where removals matter; sometimes a budget large enough to walk straight.
  const k = size === 'large' ? 1 + pick(20) : (rand() < 0.8 ? 1 + pick(Math.min(3, m * n)) : 1 + pick(m * n));
  return [grid, k];
}
